def gdown(grid,bg):
    h=len(grid); w=len(grid[0]); cols=[]
    for c in range(w):
        vals=[grid[r][c] for r in range(h) if grid[r][c]!=bg]
        cols.append([bg]*(h-len(vals))+vals)
    return [list(r) for r in zip(*cols)]
